//! Actual public command proof. Own namespace/scratch only, never a shared daemon.
//! Usage: native_analyze_cli_proof ABS_DMBC ABS_ANALYZE
//! Baseline oracle explicitly uses the supported as-of DQ_BASELINE_NO_GEN mode;
//! this does not certify default generator/check cutover or the unported union.
#[path="../../../shared/test_scratch.rs"]mod test_scratch;
use std::{error::Error,fs::{self,File},io::{self,Read,Write},path::{Path,PathBuf},process::{Command,Stdio,Child,Output},thread,time::{Duration,Instant},ffi::OsString};
use dmbc::daemon::analyze::{AnalyzeRequest,BaselineMode};
const TEST_OUTPUT:usize=4*1024*1024;
struct Running{child:Child,done:bool}impl Drop for Running{fn drop(&mut self){if !self.done{let _=self.child.kill();let _=self.child.wait();}}}
fn child(mut command:Command)->io::Result<Output>{command.stdin(Stdio::null()).stdout(Stdio::piped()).stderr(Stdio::piped());#[cfg(windows)]{use std::os::windows::process::CommandExt;command.creation_flags(0x0800_0000|0x0000_4000);}let mut running=Running{child:command.spawn()?,done:false};let stdout=running.child.stdout.take().unwrap();let stderr=running.child.stderr.take().unwrap();let reader=|input:Box<dyn Read+Send>|thread::spawn(move||{let mut bytes=Vec::new();input.take((TEST_OUTPUT+1)as u64).read_to_end(&mut bytes)?;if bytes.len()>TEST_OUTPUT{return Err(io::Error::new(io::ErrorKind::InvalidData,"test command exceeded fixture output bound"))}Ok::<_,io::Error>(bytes)});let out=reader(Box::new(stdout));let err=reader(Box::new(stderr));let until=Instant::now()+Duration::from_secs(300);let status=loop{if let Some(status)=running.child.try_wait()?{break status}if Instant::now()>=until{return Err(io::Error::new(io::ErrorKind::TimedOut,"owned command exceeded integration test cap"))}thread::sleep(Duration::from_millis(10));};running.done=true;let stdout=out.join().map_err(|_|io::Error::other("stdout reader panic"))??;let stderr=err.join().map_err(|_|io::Error::other("stderr reader panic"))??;Ok(Output{status,stdout,stderr})}
struct OwnedDaemon{program:PathBuf,namespace:String,done:bool}
impl OwnedDaemon{fn command(&self)->Command{let mut command=Command::new(&self.program);command.env("DMB_DAEMON_NAMESPACE",&self.namespace).env("DMB_DAEMON_AUTOSTART","1").env("DMB_FORWARDED","1").env("RAYON_NUM_THREADS","1").env_remove("DMB_UNIFIED_ANALYSIS");command}fn retire(&mut self)->Result<(),Box<dyn Error>>{let mut command=self.command();command.arg("--daemon-retire");let result=child(command)?;if !result.status.success(){return Err(format!("own namespace retirement failed: {}",String::from_utf8_lossy(&result.stderr)).into())}self.done=true;Ok(())}}
impl Drop for OwnedDaemon{fn drop(&mut self){if !self.done{let mut command=self.command();command.arg("--daemon-retire");let _=child(command);}}}
fn fixture(root:&Path)->io::Result<()>{fs::create_dir_all(root.join("code"))?;fs::create_dir_all(root.join("tools/ci"))?;fs::write(root.join("deepquarry.dme"),"#include \"code/0000.dm\"\n")?;for n in 0..129{fs::write(root.join(format!("code/{n:04}.dm")),format!("/proc/report_probe{n}()\n    sleep(1) // ALLOW(scheduler): synchronous external operation requires an actual wait\n    sleep(2)\n    qdel(src)\n"))?;}fs::write(root.join("tools/ci/lint_scopes.toml"),include_bytes!("../../../../../tools/ci/lint_scopes.toml"))?;Ok(())}
fn legacy(program:&Path,root:&Path,cache:&Path,baseline:Option<&str>,raw:bool,ci:bool,lints:&[&str])->io::Result<Output>{let mut command=Command::new(program);command.current_dir(root).arg(if baseline.is_some(){"baseline"}else{"check"}).arg("--root").arg(root).arg("--no-cache").arg("--no-selftest");for name in lints{command.arg("--lint").arg(name);}if raw{command.arg("--raw");}if ci{command.arg("--ci");}if let Some(mode)=baseline{command.arg(mode).env("DQ_BASELINE_NO_GEN","1");}command.env("RAYON_NUM_THREADS","1").env("DQ_ANALYZE_CACHE",cache.join("legacy-cache")).env("DQ_ALLOW_USAGE",cache.join("legacy-allow.tsv")).env_remove("DQ_ANALYZE_TRACE").env_remove("DQ_ANALYZE_TRACE_INCR");child(command)}
fn native_request(root:&Path,cache:&Path,lints:&[&str],raw:bool,ci:bool,baseline_mode:Option<BaselineMode>)->Result<AnalyzeRequest,Box<dyn Error>>{let project=root.join("deepquarry.dme");let args=vec!["prepare-query".to_owned(),project.to_string_lossy().into_owned()];let dmbc::request::Command::Build(build)=dmbc::cli::parse(&args)?else{return Err("real PrepareQuery parser changed".into())};let mut build=*build;let template=cache.join("template.bin");if !template.exists(){fs::write(&template,include_bytes!("../../../fixtures/native_template.bin"))?;}build.engine_template=Some(template);build.bootstrap_catalog=true;build.workers=1;build.no_cache=true;build.exact_inputs=true;build.progress_enabled=false;build.cache_root=Some(cache.to_path_buf());build.timeout_seconds=Some(300);let mut policy=dmbc::policy_request::PolicyInputRequest::default();policy.workspace=Some(dmbc::policy_request::WorkspacePolicyRequest{root:root.to_path_buf(),recursive_roots:vec![root.join("code"),root.join("maps")],configuration:root.join("tools/ci/lint_scopes.toml")});build.policy_inputs=Some(policy);Ok(AnalyzeRequest{build,lints:lints.iter().map(|name|(*name).to_owned()).collect(),raw,changed:None,scopes_root:None,baseline_mode,ci})}
fn native(daemon:&OwnedDaemon,analyze:&Path,request:&AnalyzeRequest,cache:&Path,thin:bool)->Result<(i32,serde_json::Value),Box<dyn Error>>{let path=cache.join("actual request [pinned] α.json");fs::write(&path,serde_json::to_vec(request)?)?;let baseline=request.baseline_mode.is_some();let mut command=if thin{let mut c=Command::new(analyze);c.arg(if baseline{"native-baseline"}else{"native-check"}).arg("--dmbc").arg(&daemon.program).env("DMB_DAEMON_NAMESPACE",&daemon.namespace).env("DMB_DAEMON_AUTOSTART","1").env("DMB_FORWARDED","1").env("RAYON_NUM_THREADS","1");c}else{let mut c=daemon.command();c.arg(if baseline{"analyze-baseline"}else{"analyze-check"});c};command.arg(&path).arg("--jsonl").env("DQ_ALLOW_USAGE",cache.join("native-allow.tsv"));let result=child(command)?;let code=result.status.code().ok_or("command terminated without exit status")?;if !matches!(code,0|1){return Err(format!("native command failed {code}: {}",String::from_utf8_lossy(&result.stderr)).into())}let row:serde_json::Value=serde_json::from_slice(&result.stdout)?;if row["schema"]!="native-analyze-report-v1"||row["complete"]!=true||row["full_policy_parity"]!=false||row["baseline"]!=baseline||row["clean"]!=(code==0){return Err("actual command did not deliver a complete matching explicit-selection report".into())}for key in ["semantic_revision","source_revision","policy_revision"]{let pin=row[key].as_str().ok_or("missing pin")?;if pin.len()!=32||!pin.bytes().all(|b|b.is_ascii_digit()||(b'a'..=b'f').contains(&b)){return Err("invalid actual retained pin".into())}}Ok((code,row))}
fn compare(old:Output,new:&(i32,serde_json::Value))->Result<(),Box<dyn Error>>{if old.status.code()!=Some(new.0){return Err(format!("old/native status differs {:?}/{}; oldstderr {}",old.status.code(),new.0,String::from_utf8_lossy(&old.stderr)).into())}let text=new.1["text"].as_str().ok_or("missing complete text")?;if old.stdout!=text.as_bytes(){return Err(format!("WHOLE report differs\nOLD:\n{}\nNATIVE:\n{text}",String::from_utf8_lossy(&old.stdout)).into())}Ok(())}
fn main()->Result<(),Box<dyn Error>>{let args=std::env::args_os().skip(1).collect::<Vec<OsString>>();if args.len()!=2{return Err("usage: native_analyze_cli_proof ABS_DMBC ABS_ANALYZE".into())}let dmbc=fs::canonicalize(PathBuf::from(&args[0]))?;let analyze=fs::canonicalize(PathBuf::from(&args[1]))?;let outer=test_scratch::dir("native-analyze-real-command");let old=outer.join("old");let fresh=outer.join("native");let cache=outer.join("cache");fs::create_dir_all(&cache)?;fixture(&old)?;fixture(&fresh)?;let old=fs::canonicalize(old)?;let fresh=fs::canonicalize(fresh)?;let cache=fs::canonicalize(cache)?;let mut daemon=OwnedDaemon{program:dmbc,namespace:format!("public-report-cli-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH)?.as_millis()),done:false};
 // External proof timeout cleanup must target ONLY this test-owned namespace.
 if !daemon.namespace.starts_with("public-report-cli-")||!daemon.namespace.bytes().all(|b|b.is_ascii_alphanumeric()||b==b'-'){return Err("invalid test-owned daemon namespace".into())}
 if let Some(path)=std::env::var_os("DMB_PROOF_NAMESPACE_FILE"){let path=PathBuf::from(path);if !path.is_absolute(){return Err("proof namespace handshake path must be absolute".into())}let mut file=fs::OpenOptions::new().write(true).create_new(true).open(path)?;writeln!(&mut file,"{}",daemon.namespace)?;file.sync_all()?;}
 eprintln!("OWNED_DAEMON_NAMESPACE={}",daemon.namespace);
 let request=native_request(&fresh,&cache,&["scheduler","qdel_src"],true,true,None)?;let first=native(&daemon,&analyze,&request,&cache,false)?;assert_eq!(first.0,1);compare(legacy(&analyze,&old,&cache,None,true,true,&["scheduler","qdel_src"])? ,&first)?;assert_eq!(fs::read(cache.join("legacy-allow.tsv"))?,fs::read(cache.join("native-allow.tsv"))?,"actual completed command preserves entire legacy ALLOW usage append bytes");assert_eq!(first.1["allow_usage"].as_array().unwrap().len(),129);let thin=native(&daemon,&analyze,&request,&cache,true)?;assert_eq!(thin,first,"warm actual command and thin delivery preserve the entire pinned report");
 let baseline=native_request(&fresh,&cache,&["scheduler"],false,false,Some(BaselineMode::Seed))?;let native_seed=native(&daemon,&analyze,&baseline,&cache,false)?;compare(legacy(&analyze,&old,&cache,Some("--seed"),false,false,&["scheduler"])? ,&native_seed)?;let baseline_path="tools/ci/scheduler_lints_baseline.txt";assert_eq!(fs::read(old.join(baseline_path))?,fs::read(fresh.join(baseline_path))?);assert_eq!(fs::read(old.join("tools/ci/lint_scopes.toml"))?,fs::read(fresh.join("tools/ci/lint_scopes.toml"))?);
 let checked=native_request(&fresh,&cache,&["scheduler"],false,false,None)?;let actual=native(&daemon,&analyze,&checked,&cache,false)?;assert_eq!(actual.0,0);compare(legacy(&analyze,&old,&cache,None,false,false,&["scheduler"])? ,&actual)?;
 for root in [&old,&fresh]{fs::remove_file(root.join("code/0128.dm"))?;}let update=native_request(&fresh,&cache,&["scheduler"],false,false,Some(BaselineMode::Update))?;let native_update=native(&daemon,&analyze,&update,&cache,true)?;compare(legacy(&analyze,&old,&cache,Some("--update"),false,false,&["scheduler"])? ,&native_update)?;assert_eq!(fs::read(old.join(baseline_path))?,fs::read(fresh.join(baseline_path))?);assert_ne!(native_update.1["policy_revision"],actual.1["policy_revision"],"real raw-file removal advances current policy capture");

 // Custom finish must compare at the SAME real root: its original messages
 // contain the absolute fixed allowlist path. No path/text filtering is used.
 let deadline_root=outer.join("deadline");fixture(&deadline_root)?;let deadline_root=fs::canonicalize(deadline_root)?;
 fs::write(deadline_root.join("code/0000.dm"),"/datum/probe/proc/process()\n\tif(world.time >= next_fire)\n\t\treturn\n")?;
 let allow=deadline_root.join("tools/ci/deadline_polling_allowlist.txt");
 for (case,bytes,code) in [("reason",Some(b"code/0000.dm:/datum/probe/process # actual compatibility behavior is retained\n".as_slice()),0),("reasonless",Some(b"code/0000.dm:/datum/probe/process\n".as_slice()),1),("missing",None,1),("non_utf8",Some([255u8].as_slice()),1)]{
  if let Some(bytes)=bytes{fs::write(&allow,bytes)?;}else if allow.exists(){fs::remove_file(&allow)?;}
  let mut request=native_request(&deadline_root,&cache,&["deadline_polling"],false,false,None)?;
  request.build.policy_inputs.as_mut().unwrap().workspace_auxiliary=vec![dmbc::policy_request::WorkspaceAuxiliaryQuestion::DeadlinePollingAllowlist];
  let result=native(&daemon,&analyze,&request,&cache,case=="reasonless")?;assert_eq!(result.0,code,"{case}");compare(legacy(&analyze,&deadline_root,&cache,None,false,false,&["deadline_polling"])? ,&result)?;
  if case=="reason"{assert_eq!(native(&daemon,&analyze,&request,&cache,true)?,result,"custom warm report must preserve all actual pins and old text");}
 }
 // Baseline is the original hand-maintained custom hook and requests no
 // irrelevant auxiliary file read, even while that file is malformed UTF-8.
 let request=native_request(&deadline_root,&cache,&["deadline_polling"],false,false,Some(BaselineMode::Update))?;
 assert!(request.build.policy_inputs.as_ref().unwrap().workspace_auxiliary.is_empty());
 let result=native(&daemon,&analyze,&request,&cache,false)?;compare(legacy(&analyze,&deadline_root,&cache,Some("--update"),false,false,&["deadline_polling"])? ,&result)?;

 let hygiene_old=outer.join("hygiene-old");let hygiene_new=outer.join("hygiene-native");for root in [&hygiene_old,&hygiene_new]{fixture(root)?;fs::create_dir(root.join("maps"))?;fs::write(root.join("code/0000.dm"),"/obj/report_hygiene\n\tvar/cached_charge\n/obj/report_hygiene/proc/process()\n\tif(world.time > next_move) // ALLOW(sys_deadline_poll): this whole source fixture intentionally observes polling\n\t\treturn\n\tcached_charge=2\n\t// ALLOW(scheduler): baseline when ci was wired\n")?;fs::write(root.join("maps/only.dm"),"/obj/map_hygiene\n\tvar/cached_map\n")?;}
 let hygiene_old=fs::canonicalize(hygiene_old)?;let hygiene_new=fs::canonicalize(hygiene_new)?;
 let request=native_request(&hygiene_new,&cache,&["sys/hygiene"],true,true,None)?;let result=native(&daemon,&analyze,&request,&cache,false)?;assert_eq!(result.0,1);compare(legacy(&analyze,&hygiene_old,&cache,None,true,true,&["sys/hygiene"])? ,&result)?;assert_eq!(native(&daemon,&analyze,&request,&cache,true)?,result,"whole Hygiene source-as-of report repeats exactly; page refold cost unqualified");
 let request=native_request(&hygiene_new,&cache,&["sys/hygiene"],false,false,Some(BaselineMode::Seed))?;let result=native(&daemon,&analyze,&request,&cache,true)?;compare(legacy(&analyze,&hygiene_old,&cache,Some("--seed"),false,false,&["sys/hygiene"])? ,&result)?;assert_eq!(fs::read(hygiene_old.join("tools/ci/sys_baseline/hygiene.txt"))?,fs::read(hygiene_new.join("tools/ci/sys_baseline/hygiene.txt"))?);assert_eq!(fs::read(hygiene_old.join("tools/ci/lint_scopes.toml"))?,fs::read(hygiene_new.join("tools/ci/lint_scopes.toml"))?);
 let request=native_request(&hygiene_new,&cache,&["sys/hygiene"],false,false,None)?;let result=native(&daemon,&analyze,&request,&cache,false)?;assert_eq!(result.0,0);compare(legacy(&analyze,&hygiene_old,&cache,None,false,false,&["sys/hygiene"])? ,&result)?;

 // These three full policies have distinct complete issuers; no mixed RAW role.
 for(name,baseline)in [("sys/resolvers","tools/ci/sys_baseline/resolvers.txt"),("sys/tables","tools/ci/sys_baseline/tables.txt"),("system_boundary","tools/ci/system_boundary_baseline.txt")]{
  let label=name.replace('/',"-");let old=outer.join(format!("{label}-old"));let new=outer.join(format!("{label}-native"));
  for dir in [&old,&new]{fixture(dir)?;fs::create_dir(dir.join("maps"))?;fs::create_dir_all(dir.join("code/owner"))?;fs::write(dir.join("code/owner/system.dm"),"/datum/system/alpha\n")?;fs::write(dir.join("maps/roots.dm"),"CAPABILITIES(/obj/resolved)\n\tmap_resolver(GLOBAL_PROC_REF(resolve))\nGLOBAL_LIST_INIT(shared,list(1))\n/proc/map_reader()\n    system(/datum/system/alpha).hidden\n")?;fs::write(dir.join("code/0000.dm"),"/obj/resolved/report/proc/Initialize()\n\tif(condition)\n\t\treturn INITIALIZE_HINT_QDEL\n/obj/resolved/report/proc/values()\n\tvar/static/list/shared_values = list(1)\n\treturn shared_values\n/proc/read_system()\n    system(/datum/system/alpha).hidden\n")?;}
  let old=fs::canonicalize(old)?;let new=fs::canonicalize(new)?;
  eprintln!("ACTUAL_SYS_REPORT_FAMILY={name}");
  let request=native_request(&new,&cache,&[name],true,true,None)?;let result=native(&daemon,&analyze,&request,&cache,false)?;assert_eq!(result.0,1,"{name}: actual positive fixture must fail before seeding");compare(legacy(&analyze,&old,&cache,None,true,true,&[name])?,&result)?;assert_eq!(native(&daemon,&analyze,&request,&cache,true)?,result,"entire as-of report/ALLOW/footer and immutable pins repeat, without shared-refold-work claim");
  let request=native_request(&new,&cache,&[name],false,false,Some(BaselineMode::Seed))?;let result=native(&daemon,&analyze,&request,&cache,true)?;compare(legacy(&analyze,&old,&cache,Some("--seed"),false,false,&[name])?,&result)?;assert_eq!(fs::read(old.join(baseline))?,fs::read(new.join(baseline))?);assert_eq!(fs::read(old.join("tools/ci/lint_scopes.toml"))?,fs::read(new.join("tools/ci/lint_scopes.toml"))?);
  let request=native_request(&new,&cache,&[name],false,false,None)?;let result=native(&daemon,&analyze,&request,&cache,false)?;assert_eq!(result.0,0,"{name}: actual seeded fixture must pass");compare(legacy(&analyze,&old,&cache,None,false,false,&[name])?,&result)?;
 }
 daemon.retire()?;println!("NATIVE_ANALYZE_ACTUAL_CLI_PROOF=whole-old-check-exit1-ci+thin-warm+baseline-seed+check-exit0+baseline-update; as-of baseline no-gen oracle; explicit policies only");Ok(())}
